-- Trenerki Academy: reproducible content-only update for the Bednarz course.
-- Does not touch ta_learning_progress, ta_exam_results, customers, payments or publication flags.
BEGIN;
insert into public.ta_lessons (course_slug,lesson_no,title_pl,material)
values
('bednarz',0,'1. Anatomia beczki: co utrzymuje kształt i szczelność','{"module":1,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Od przedmiotu do budowy","text":"Beczka jest naczyniem z kilkunastu lub kilkudziesięciu klepek — długich elementów drewnianych wyprofilowanych wzdłuż i na krawędziach. Klepki tworzą płaszcz, a obręcze utrzymują je w ścisku. W tradycyjnej beczce do cieczy szczelność wynika przede wszystkim z geometrii połączeń, właściwości drewna i docisku, nie z zalania wszystkich szpar klejem."},{"heading":"Nazwy części na przekroju","text":"Płaszcz tworzą klepki; największe wybrzuszenie nazywa się brzuścem (ang. bilge). Obręcze są rozmieszczone na różnych wysokościach. Dno (ang. head) osadza się w rowku wykonanym od wewnątrz, zwanym croze lub wręgą. Krawędź końcowa beczki (chime) chroni strefę dna. Otwór szpuntowy, jeśli występuje, służy do napełniania albo opróżniania."},{"heading":"Dlaczego beczka jest wybrzuszona","text":"Klepka nie jest zwykłą prostą deską. Szersza w okolicy brzuśca, węższa przy końcach i odpowiednio profilowana, po zestawieniu tworzy naczynie o obwodzie zmieniającym się z wysokością. Obręcze utrzymują tę geometrię. Przy złym kącie styku między klepkami może powstać wąska szczelina ciągnąca się wzdłuż naczynia."},{"heading":"Zobacz zależność przyczynową","text":"Gdy obluzuje się obręcz, płaszcz może stracić odpowiedni docisk; gdy pęknie klepka, samo dociśnięcie nie zawsze pomoże. W przecieku przy dnie sprawdza się także strefę wręgi i krawędź denka. Te trzy rodzaje usterki wymagają różnych rozpoznań."},{"heading":"Ćwiczenie projektowe","text":"Narysuj przekrój pionowy beczki. Podpisz: klepka, brzusiec, trzy obręcze, denko, wręga, krawędź chime i opcjonalny szpunt. Trzema strzałkami pokaż, co zapewnia docisk, co zamyka czoło naczynia i gdzie mogą pojawić się przecieki."}],"illustration":"bednarz-anatomia","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://metc.org/decoding-the-past-cooper/"}],"learning":{"intro":"Beczka jest naczyniem z kilkunastu lub kilkudziesięciu klepek — długich elementów drewnianych wyprofilowanych wzdłuż i na krawędziach. Klepki tworzą płaszcz, a obręcze utrzymują je w ścisku. W tradycyjnej beczce do cieczy szczelność wynika przede wszystkim z geometrii połączeń, właściwości drewna i docisku, nie z zalania wszystkich szpar klejem.","situation":"Gdy obluzuje się obręcz, płaszcz może stracić odpowiedni docisk; gdy pęknie klepka, samo dociśnięcie nie zawsze pomoże. W przecieku przy dnie sprawdza się także strefę wręgi i krawędź denka. Te trzy rodzaje usterki wymagają różnych rozpoznań.","question":"Woda pojawia się tuż przy styku dna z płaszczem. Który element należy rozpoznać na rysunku jako pierwszy?","options":["Wyłącznie szerokość obręczy środkowej.","Oznaczenie gatunku na powierzchni zewnętrznej.","Połączenie krawędzi denka z wewnętrzną wręgą (croze).","Kolor zewnętrznego wykończenia bez sprawdzenia wnętrza."],"correct":2,"example":"Połączenie krawędzi denka z wewnętrzną wręgą (croze).","explanation":"Rowek croze utrzymuje krawędź dna; przeciek w tej strefie wymaga kontroli osadzenia denka, stanu drewna i docisku.","feedback":["To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Rowek croze utrzymuje krawędź dna; przeciek w tej strefie wymaga kontroli osadzenia denka, stanu drewna i docisku.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Rowek croze utrzymuje krawędź dna; przeciek w tej strefie wymaga kontroli osadzenia denka, stanu drewna i docisku.","Tak. Rowek croze utrzymuje krawędź dna; przeciek w tej strefie wymaga kontroli osadzenia denka, stanu drewna i docisku.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Rowek croze utrzymuje krawędź dna; przeciek w tej strefie wymaga kontroli osadzenia denka, stanu drewna i docisku."],"task":"Narysuj przekrój pionowy beczki. Podpisz: klepka, brzusiec, trzy obręcze, denko, wręga, krawędź chime i opcjonalny szpunt. Trzema strzałkami pokaż, co zapewnia docisk, co zamyka czoło naczynia i gdzie mogą pojawić się przecieki."}}'::jsonb),
('bednarz',1,'2. Materiałoznawstwo: dąb, włókna, porowatość i wilgotność','{"module":1,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Drewno jest materiałem anizotropowym","text":"Właściwości drewna zależą od kierunku względem włókien. Gdy klepka ma sęk, skręt włókien albo pęknięcie przecinające jej powierzchnię, ścieżka możliwego przecieku może przejść przez ścianę. Nie należy wybierać materiału tylko po kolorze. Przed oceną jakości istotne są gatunek, przebieg włókien, wilgotność, wady i przeznaczenie naczynia."},{"heading":"Nie każdy dąb zachowuje się tak samo","text":"Amerykański biały dąb (Quercus alba) ma w twardzieli struktury zwane tylosami, które mogą ograniczać przepuszczalność naczyń. Europejskie dęby używane w beczkach do wina, np. Quercus robur i Q. petraea, często wymagają łupania wzdłuż włókien w procesie doboru klepek. Nie przenoś automatycznie technologii jednego gatunku na drugi."},{"heading":"Biel, twardziel i warunki użycia","text":"Biel jest zewnętrzną strefą drewna żywego, a twardziel może mieć odmienną przepuszczalność i odporność. Dobór do beczek do napojów wymaga wymagań jakości i zgodności materiałowej: materiał powinien być znanego pochodzenia, czysty i odpowiednio sezonowany. Drewno dekoracyjne nie musi spełniać tych samych wymagań co naczynie użytkowe."},{"heading":"Przykład z wadą materiału","text":"Porównaj trzy próbki: A ma wzdłużne, nieskręcone włókna bez pęknięć; B ma duży sęk na krawędzi; C ma widoczną szczelinę ciągnącą się przez grubość. Przy identycznym szablonie A jest lepszym kandydatem, ale dopiero komplet pomiarów i wymogów potwierdzi przydatność."},{"heading":"Ćwiczenie z kontrolą dostawy","text":"Zbuduj kartę selekcji dla 12 klepek: numer, gatunek, pochodzenie, przebieg włókien, pęknięcia, sęki, wilgotność według właściwej metody, decyzja i uzasadnienie. Osobno zapisz, które wady można rozpoznać wizualnie, a które wymagają pomiaru lub specjalisty."}],"illustration":"material-bednarz","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://www.bouchardcooperages.com/wine-barrels-faq"}],"learning":{"intro":"Właściwości drewna zależą od kierunku względem włókien. Gdy klepka ma sęk, skręt włókien albo pęknięcie przecinające jej powierzchnię, ścieżka możliwego przecieku może przejść przez ścianę. Nie należy wybierać materiału tylko po kolorze. Przed oceną jakości istotne są gatunek, przebieg włókien, wilgotność, wady i przeznaczenie naczynia.","situation":"Porównaj trzy próbki: A ma wzdłużne, nieskręcone włókna bez pęknięć; B ma duży sęk na krawędzi; C ma widoczną szczelinę ciągnącą się przez grubość. Przy identycznym szablonie A jest lepszym kandydatem, ale dopiero komplet pomiarów i wymogów potwierdzi przydatność.","question":"Dlaczego proces doboru klepek z dębu europejskiego może preferować łupanie wzdłuż włókien?","options":["Ponieważ łupanie zawsze daje idealnie równą szerokość bez późniejszej obróbki.","Ponieważ przebieg włókien może mieć krytyczne znaczenie dla drogi przecieku przez drewno.","Ponieważ wszystkie dęby mają identyczną porowatość i konstrukcję naczyń.","Ponieważ obręcze zastępują konieczność kontroli pęknięć."],"correct":1,"example":"Ponieważ przebieg włókien może mieć krytyczne znaczenie dla drogi przecieku przez drewno.","explanation":"Przecięcie włókien w niekorzystny sposób może utworzyć drogę przepływu; gatunki różnią się anatomią i technologią przygotowania.","feedback":["To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Przecięcie włókien w niekorzystny sposób może utworzyć drogę przepływu; gatunki różnią się anatomią i technologią przygotowania.","Tak. Przecięcie włókien w niekorzystny sposób może utworzyć drogę przepływu; gatunki różnią się anatomią i technologią przygotowania.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Przecięcie włókien w niekorzystny sposób może utworzyć drogę przepływu; gatunki różnią się anatomią i technologią przygotowania.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Przecięcie włókien w niekorzystny sposób może utworzyć drogę przepływu; gatunki różnią się anatomią i technologią przygotowania."],"task":"Zbuduj kartę selekcji dla 12 klepek: numer, gatunek, pochodzenie, przebieg włókien, pęknięcia, sęki, wilgotność według właściwej metody, decyzja i uzasadnienie. Osobno zapisz, które wady można rozpoznać wizualnie, a które wymagają pomiaru lub specjalisty."}}'::jsonb),
('bednarz',2,'3. Warsztat bednarza: narzędzia, przeznaczenie i konserwacja','{"module":1,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Rozpoznaj stanowisko","text":"Klepki obrabia się z użyciem stabilnego podparcia i przyrządów do ich unieruchomienia. Tradycyjne narzędzia obejmują m.in. ośnik (drawknife), strug, bednarkę/strug krawędziowy, dłuta i narzędzia do osadzania obręczy. Specjalne narzędzie croze wykonuje rowek na denko. Nie myl obręczy, będącej częścią wyrobu, z narzędziem do jej nasadzania."},{"heading":"Dlaczego strug i croze nie są zamienne","text":"Strug przygotowuje powierzchnię lub krawędź klepki; croze tworzy rowek wewnątrz złożonego płaszcza na odpowiedniej wysokości. Nawet idealnie strugana klepka nie przyjmie denka bez właściwej geometrii rowka. Przy kontroli narzędzia pytaj: jaki kształt uzyskuje, od jakiej bazy pracuje i co mogę zmierzyć po operacji."},{"heading":"Narzędzie do obręczy","text":"Młotek bednarski i odpowiednia nakładka/pobijak do obręczy pozwalają przekazywać siłę w przewidzianym miejscu. Uderzenie bezpośrednio ciężkim stalowym młotem w drewno może uszkodzić krawędź klepek. Zwróć uwagę na ergonomię, stabilne ustawienie i kierunek przenoszenia sił."},{"heading":"Konserwacja i bezpieczna ocena","text":"Przed pracą kontroluj stan rękojeści, mocowania ostrza, pęknięcia, korozję, osłony i zgodność narzędzia z operacją. Przechowuj ostrza w osłonach i stosuj sposób ostrzenia przewidziany dla danego narzędzia. Ćwiczenia z ostrymi narzędziami lub obręczami wykonuje się wyłącznie w przygotowanym warsztacie pod nadzorem fachowca."},{"heading":"Ćwiczenie rozpoznawcze","text":"Przygotuj tabelę sześciu narzędzi: nazwa polska/angielska, operacja, powierzchnia bazowa, rezultat, typowa wada i punkt kontroli. Dla croze wskaż rowek, dla ośnika wstępne kształtowanie, a dla pobijaka osadzanie obręczy."}],"illustration":"technique-bednarz","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://metc.org/decoding-the-past-cooper/"}],"learning":{"intro":"Klepki obrabia się z użyciem stabilnego podparcia i przyrządów do ich unieruchomienia. Tradycyjne narzędzia obejmują m.in. ośnik (drawknife), strug, bednarkę/strug krawędziowy, dłuta i narzędzia do osadzania obręczy. Specjalne narzędzie croze wykonuje rowek na denko. Nie myl obręczy, będącej częścią wyrobu, z narzędziem do jej nasadzania.","situation":"Przed pracą kontroluj stan rękojeści, mocowania ostrza, pęknięcia, korozję, osłony i zgodność narzędzia z operacją. Przechowuj ostrza w osłonach i stosuj sposób ostrzenia przewidziany dla danego narzędzia. Ćwiczenia z ostrymi narzędziami lub obręczami wykonuje się wyłącznie w przygotowanym warsztacie pod nadzorem fachowca.","question":"Jaka operacja odróżnia narzędzie croze od zwykłego struga do klepek?","options":["Wykonuje wewnętrzny rowek do osadzenia denka.","Mierzy wilgotność drewna metodą masową.","Zmienia skład chemiczny stali obręczy.","Rozpoznaje gatunek drewna po samym kolorze."],"correct":0,"example":"Wykonuje wewnętrzny rowek do osadzenia denka.","explanation":"Croze służy do rowka pod denko, a strug do obróbki powierzchni lub krawędzi; to różne punkty technologiczne.","feedback":["Tak. Croze służy do rowka pod denko, a strug do obróbki powierzchni lub krawędzi; to różne punkty technologiczne.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Croze służy do rowka pod denko, a strug do obróbki powierzchni lub krawędzi; to różne punkty technologiczne.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Croze służy do rowka pod denko, a strug do obróbki powierzchni lub krawędzi; to różne punkty technologiczne.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Croze służy do rowka pod denko, a strug do obróbki powierzchni lub krawędzi; to różne punkty technologiczne."],"task":"Przygotuj tabelę sześciu narzędzi: nazwa polska/angielska, operacja, powierzchnia bazowa, rezultat, typowa wada i punkt kontroli. Dla croze wskaż rowek, dla ośnika wstępne kształtowanie, a dla pobijaka osadzanie obręczy."}}'::jsonb),
('bednarz',3,'4. Rysunek techniczny beczki: obwód, klepki i tolerancje','{"module":1,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Czytaj widoki, a nie tylko obrazek","text":"Rysunek beczki powinien określać co najmniej wysokość, średnicę w strefie brzuśca i przy denku, grubość klepki, położenie obręczy oraz szczegóły wręgi. Widok z boku pokazuje profil, rzut z góry obwód i podział na klepki, a przekrój pozwala oznaczyć grubości i rowek."},{"heading":"Przykład: obwód i średnia szerokość","text":"Dla średnicy zewnętrznej D = 600 mm, obwód koła na tej wysokości wynosi C = π × D ≈ 1885 mm. Jeśli projekt przewiduje 20 klepek, orientacyjny średni udział jednej na obwodzie zewnętrznym wynosi 1885/20 ≈ 94,2 mm. To tylko kontrola szacunkowa, nie wymiar rozkroju: liczą się kąty, krzywizna, szerokości klepek i rzeczywisty przekrój."},{"heading":"Dlaczego profil zmienia rachunek","text":"Na końcach beczka jest zwykle węższa niż przy brzuścu. Gdy w tym samym przykładzie średnica przy końcu wynosi 500 mm, tamtejszy obwód to około 1571 mm, czyli średnio 78,5 mm na klepkę przy założeniu 20 sztuk. Właśnie dlatego nie wytniesz dwudziestu idealnych prostokątów o jednej stałej szerokości."},{"heading":"Wymiar nominalny i pomiar kontrolny","text":"Nie odczytuj wymiarów z przypadkowo zmniejszonego wydruku bez uwzględnienia skali. Rozróżniaj średnicę zewnętrzną i wewnętrzną; objętość użytkowa nie wynika z samej średnicy brzuśca. W dokumentacji określ także sposób pomiaru owalizacji i tolerancję dla wyrobu."},{"heading":"Ćwiczenie na kartce","text":"Narysuj profil D_brzuśca = 600 mm, D_końca = 500 mm, wysokość 900 mm. Zaznacz 20 klepek, wylicz dwa obwody i porównaj średnie udziały szerokości. Napisz, których wymiarów jeszcze brakuje, aby projekt nadawał się do wykonania."}],"illustration":"bednarz-geometria","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://www.saury.com/en/our-skills/the-stages-of-barrel-making/"}],"learning":{"intro":"Rysunek beczki powinien określać co najmniej wysokość, średnicę w strefie brzuśca i przy denku, grubość klepki, położenie obręczy oraz szczegóły wręgi. Widok z boku pokazuje profil, rzut z góry obwód i podział na klepki, a przekrój pozwala oznaczyć grubości i rowek.","situation":"Nie odczytuj wymiarów z przypadkowo zmniejszonego wydruku bez uwzględnienia skali. Rozróżniaj średnicę zewnętrzną i wewnętrzną; objętość użytkowa nie wynika z samej średnicy brzuśca. W dokumentacji określ także sposób pomiaru owalizacji i tolerancję dla wyrobu.","question":"Przy D=600 mm i 20 klepkach wartość C/20 ≈ 94 mm oznacza przede wszystkim...","options":["Gwarantowaną szerokość cięcia każdej klepki w całej długości.","Głębokość rowka na denko.","Grubość stalowej obręczy przy brzuścu.","Orientacyjny udział jednej klepki w zewnętrznym obwodzie tej wysokości."],"correct":3,"example":"Orientacyjny udział jednej klepki w zewnętrznym obwodzie tej wysokości.","explanation":"Dzielenie obwodu przez liczbę klepek pomaga w oszacowaniu; nie uwzględnia geometrii styku, obróbki ani różnicy szerokości na wysokości.","feedback":["To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Dzielenie obwodu przez liczbę klepek pomaga w oszacowaniu; nie uwzględnia geometrii styku, obróbki ani różnicy szerokości na wysokości.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Dzielenie obwodu przez liczbę klepek pomaga w oszacowaniu; nie uwzględnia geometrii styku, obróbki ani różnicy szerokości na wysokości.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Dzielenie obwodu przez liczbę klepek pomaga w oszacowaniu; nie uwzględnia geometrii styku, obróbki ani różnicy szerokości na wysokości.","Tak. Dzielenie obwodu przez liczbę klepek pomaga w oszacowaniu; nie uwzględnia geometrii styku, obróbki ani różnicy szerokości na wysokości."],"task":"Narysuj profil D_brzuśca = 600 mm, D_końca = 500 mm, wysokość 900 mm. Zaznacz 20 klepek, wylicz dwa obwody i porównaj średnie udziały szerokości. Napisz, których wymiarów jeszcze brakuje, aby projekt nadawał się do wykonania."}}'::jsonb),
('bednarz',4,'5. Przygotowanie klepki: rozkrój, sezonowanie i styk','{"module":2,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Od kłody do elementu roboczego","text":"Przygotowanie zaczyna się od selekcji surowca, przetarcia lub łupania zależnie od gatunku, wstępnego wymiarowania i odpowiedniego sezonowania. Niektóre dębowe klepki do beczek spożywczych wymagają długiego przygotowania, aby uzyskać pożądaną wilgotność i właściwości. Nie ma jednej uniwersalnej liczby miesięcy dla wszystkich beczek."},{"heading":"Trzy różne płaszczyzny klepki","text":"Klepka ma powierzchnię wewnętrzną, zewnętrzną i boczne krawędzie stykające się z sąsiadkami. Poprawny kształt wymaga kontroli po długości oraz właściwego kąta krawędzi. Nawet gdy powierzchnia zewnętrzna wygląda gładko, krawędź boczna może tworzyć szczelinę, której obręcz nie zniweluje."},{"heading":"Przebieg włókien i obrabialność","text":"Przy przygotowaniu obserwuje się przebieg włókien, możliwe pęknięcia i zachowanie drewna podczas skrawania. W zależności od gatunku i przeznaczenia metoda łupania lub cięcia może ograniczać przecieki. Odchylenia w geometrii trzeba sprawdzać na szablonie i przy próbnym zestawieniu."},{"heading":"Przykład błędu","text":"Dwie klepki mają identyczną szerokość pośrodku, ale jedna ma krawędź nierówną o 1,5 mm na długości 800 mm. Po zetknięciu może powstać widoczna szczelina lokalna. Przy ocenie liczą się pomiary odchyleń i rzeczywisty styk, nie średnia szerokość z jednej wysokości."},{"heading":"Zadanie kontroli procesu","text":"Sporządź kartę procesu: oznaczenie partii → kontrola włókien i wad → sezonowanie → struganie zewnętrznej i wewnętrznej powierzchni → przygotowanie krawędzi → kontrola szablonem → dopuszczenie do zestawienia. Wpisz, po którym kroku odrzucisz klepkę z pęknięciem przez grubość."}],"illustration":"technique-bednarz","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://onlinelibrary.wiley.com/doi/full/10.1002/jib.660"}],"learning":{"intro":"Przygotowanie zaczyna się od selekcji surowca, przetarcia lub łupania zależnie od gatunku, wstępnego wymiarowania i odpowiedniego sezonowania. Niektóre dębowe klepki do beczek spożywczych wymagają długiego przygotowania, aby uzyskać pożądaną wilgotność i właściwości. Nie ma jednej uniwersalnej liczby miesięcy dla wszystkich beczek.","situation":"Dwie klepki mają identyczną szerokość pośrodku, ale jedna ma krawędź nierówną o 1,5 mm na długości 800 mm. Po zetknięciu może powstać widoczna szczelina lokalna. Przy ocenie liczą się pomiary odchyleń i rzeczywisty styk, nie średnia szerokość z jednej wysokości.","question":"Dwie klepki mają właściwy obwód w brzuścu, ale jedna ma krzywą krawędź wzdłużną. Dlaczego to ważne?","options":["Ponieważ kształt krawędzi wpływa na ciągłość styku z sąsiednią klepką.","Ponieważ każdy rowek na denko sam usuwa nierówność krawędzi.","Ponieważ liczba obręczy automatycznie naprawia pęknięcia włókien.","Ponieważ średnia szerokość obwodu gwarantuje szczelność każdego styku."],"correct":0,"example":"Ponieważ kształt krawędzi wpływa na ciągłość styku z sąsiednią klepką.","explanation":"Szczelność wymaga dopasowania sąsiadujących krawędzi wzdłuż całej klepki, nie wyłącznie zgodnej średnicy w jednej strefie.","feedback":["Tak. Szczelność wymaga dopasowania sąsiadujących krawędzi wzdłuż całej klepki, nie wyłącznie zgodnej średnicy w jednej strefie.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Szczelność wymaga dopasowania sąsiadujących krawędzi wzdłuż całej klepki, nie wyłącznie zgodnej średnicy w jednej strefie.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Szczelność wymaga dopasowania sąsiadujących krawędzi wzdłuż całej klepki, nie wyłącznie zgodnej średnicy w jednej strefie.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Szczelność wymaga dopasowania sąsiadujących krawędzi wzdłuż całej klepki, nie wyłącznie zgodnej średnicy w jednej strefie."],"task":"Sporządź kartę procesu: oznaczenie partii → kontrola włókien i wad → sezonowanie → struganie zewnętrznej i wewnętrznej powierzchni → przygotowanie krawędzi → kontrola szablonem → dopuszczenie do zestawienia. Wpisz, po którym kroku odrzucisz klepkę z pęknięciem przez grubość."}}'::jsonb),
('bednarz',5,'6. Zestawianie i gięcie klepek: jak powstaje płaszcz','{"module":2,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Kolejność bez tajemnic","text":"Przy zestawianiu wstępnie przygotowane klepki ustawia się kolejno, utrzymując ich geometrię tymczasową obręczą. Powstaje otwarty płaszcz, zanim przeciwne końce zostaną ściągnięte do kształtu beczki. Metoda tradycyjna opiera się na stopniowym dostosowywaniu krzywizny z wykorzystaniem ciepła i wilgoci, ale konkretna procedura zależy od drewna i warsztatu."},{"heading":"Co robi ciepło i wilgoć","text":"Drewno pod wpływem odpowiednich warunków cieplnych i wilgotnościowych jest bardziej podatne na formowanie. Przy zbyt gwałtownym lub nierównomiernym naprężeniu może dojść do pęknięcia albo trwałego uszkodzenia. Nie należy traktować ogrzewania jako sposobu na uratowanie klepki z wadą przez grubość."},{"heading":"Obręcze jako część układu","text":"Obręcz wstępna stabilizuje rozstaw, kolejne odpowiadają za docisk na określonych wysokościach. Ich średnica i profil muszą odpowiadać wymiarom płaszcza. Zbyt luźna nie zapewni wymaganej stabilizacji, a nadmierny nacisk lub niewłaściwe narzędzie może uszkodzić drewno."},{"heading":"Bezpieczeństwo etapu","text":"Gięcie z ogniem, parą lub gorącą wodą grozi oparzeniami, pożarem i pękaniem napinanych elementów. Nauka online powinna tłumaczyć proces, nie zastępować instruktażu stanowiskowego: pracę z temperaturą, obręczami i narzędziami prowadzi instruktor w przygotowanym warsztacie."},{"heading":"Zadanie sekwencji","text":"Ułóż w kolejności: selekcja materiału, uformowanie klepek, wstępne zestawienie, kontrolowana obróbka umożliwiająca zginanie, ściągnięcie płaszcza, dopasowanie obręczy i pomiar. Wpisz po każdym etapie możliwą wadę oraz sposób jej zauważenia."}],"illustration":"craft-bednarz","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://www.saury.com/en/our-skills/the-stages-of-barrel-making/"}],"learning":{"intro":"Przy zestawianiu wstępnie przygotowane klepki ustawia się kolejno, utrzymując ich geometrię tymczasową obręczą. Powstaje otwarty płaszcz, zanim przeciwne końce zostaną ściągnięte do kształtu beczki. Metoda tradycyjna opiera się na stopniowym dostosowywaniu krzywizny z wykorzystaniem ciepła i wilgoci, ale konkretna procedura zależy od drewna i warsztatu.","situation":"Gięcie z ogniem, parą lub gorącą wodą grozi oparzeniami, pożarem i pękaniem napinanych elementów. Nauka online powinna tłumaczyć proces, nie zastępować instruktażu stanowiskowego: pracę z temperaturą, obręczami i narzędziami prowadzi instruktor w przygotowanym warsztacie.","question":"Dlaczego klepki powinny być sprawdzone przed etapem gięcia?","options":["Ponieważ po gięciu drewno przestaje być materiałem higroskopijnym.","Ponieważ każdy defekt można usunąć przez bardzo mocne ściągnięcie obręczy.","Ponieważ pęknięcia i niezgodna geometria mogą się pogłębić przy naprężeniu.","Ponieważ poprawna obręcz zwalnia z oceny jakości drewna."],"correct":2,"example":"Ponieważ pęknięcia i niezgodna geometria mogą się pogłębić przy naprężeniu.","explanation":"Naprężenie podczas formowania nie naprawia uszkodzeń; może je ujawnić lub pogłębić.","feedback":["To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Naprężenie podczas formowania nie naprawia uszkodzeń; może je ujawnić lub pogłębić.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Naprężenie podczas formowania nie naprawia uszkodzeń; może je ujawnić lub pogłębić.","Tak. Naprężenie podczas formowania nie naprawia uszkodzeń; może je ujawnić lub pogłębić.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Naprężenie podczas formowania nie naprawia uszkodzeń; może je ujawnić lub pogłębić."],"task":"Ułóż w kolejności: selekcja materiału, uformowanie klepek, wstępne zestawienie, kontrolowana obróbka umożliwiająca zginanie, ściągnięcie płaszcza, dopasowanie obręczy i pomiar. Wpisz po każdym etapie możliwą wadę oraz sposób jej zauważenia."}}'::jsonb),
('bednarz',6,'7. Denko i wręga (croze): zamykanie naczynia','{"module":2,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Jaka jest rola denka","text":"Dno beczki nie jest przymocowaną przypadkowo płytą. W tradycyjnym układzie tworzą je dopasowane elementy drewniane złączone w tarczę o odpowiednim profilu krawędzi. Brzeg denka jest osadzany w rowku wewnętrznym płaszcza. Jego usytuowanie musi współpracować z geometrią klepek oraz końcowym dociskiem."},{"heading":"Różnica: croze i krawędź chime","text":"Croze oznacza rowek biegnący wewnątrz beczki, na którym opiera się lub w którym osadza się brzeg denka. Chime oznacza końcową strefę ściany przy dnie. Błąd położenia rowka może uniemożliwić właściwe wejście denka, a uszkodzona krawędź może być objawem niewłaściwego montażu lub użytkowania."},{"heading":"Dlaczego sam okrąg nie wystarczy","text":"Kształt denka powinien wynikać z rzeczywistego obrysu i wybranej technologii. Połączenie wymaga poprawnego profilu krawędzi; samo narysowanie koła o średnicy zewnętrznej beczki nie uwzględnia rowka, grubości płaszcza ani tolerancji. Nie można też ocenić siły mocowania bez sprawdzenia obręczy."},{"heading":"Przykład pomyłki na rysunku","text":"Projektant podał 500 mm średnicy zewnętrznej końca beczki, a wykonawca od razu wycina denko 500 mm. Taki wymiar nie wynika logicznie z rysunku; potrzebna jest średnica osadzenia oraz profil rowka i denka. W dobrym projekcie każdy ważny wymiar ma nazwę i bazę."},{"heading":"Ćwiczenie z widokiem przekroju","text":"Narysuj fragment ścianki w przekroju, wskaż grubość klepki, rowek croze, krawędź chime, profil denka oraz kierunek docisku. Napisz trzy brakujące wymiary, o które zapytasz przed wykonaniem denka."}],"illustration":"bednarz-wrega","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://metc.org/decoding-the-past-cooper/"}],"learning":{"intro":"Dno beczki nie jest przymocowaną przypadkowo płytą. W tradycyjnym układzie tworzą je dopasowane elementy drewniane złączone w tarczę o odpowiednim profilu krawędzi. Brzeg denka jest osadzany w rowku wewnętrznym płaszcza. Jego usytuowanie musi współpracować z geometrią klepek oraz końcowym dociskiem.","situation":"Projektant podał 500 mm średnicy zewnętrznej końca beczki, a wykonawca od razu wycina denko 500 mm. Taki wymiar nie wynika logicznie z rysunku; potrzebna jest średnica osadzenia oraz profil rowka i denka. W dobrym projekcie każdy ważny wymiar ma nazwę i bazę.","question":"Masz tylko zewnętrzną średnicę końca beczki. Czego nie możesz z niej samodzielnie wyznaczyć?","options":["Przybliżonego obwodu zewnętrznego.","Średnicy i profilu osadzenia denka bez wymiarów wręgi i grubości.","Liczby milimetrów w metrze.","Położenia górnej krawędzi na rysunku."],"correct":1,"example":"Średnicy i profilu osadzenia denka bez wymiarów wręgi i grubości.","explanation":"Osadzenie denka jest wewnątrz płaszcza; wymaga własnych wymiarów i profilu, a nie samej średnicy zewnętrznej.","feedback":["To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Osadzenie denka jest wewnątrz płaszcza; wymaga własnych wymiarów i profilu, a nie samej średnicy zewnętrznej.","Tak. Osadzenie denka jest wewnątrz płaszcza; wymaga własnych wymiarów i profilu, a nie samej średnicy zewnętrznej.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Osadzenie denka jest wewnątrz płaszcza; wymaga własnych wymiarów i profilu, a nie samej średnicy zewnętrznej.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Osadzenie denka jest wewnątrz płaszcza; wymaga własnych wymiarów i profilu, a nie samej średnicy zewnętrznej."],"task":"Narysuj fragment ścianki w przekroju, wskaż grubość klepki, rowek croze, krawędź chime, profil denka oraz kierunek docisku. Napisz trzy brakujące wymiary, o które zapytasz przed wykonaniem denka."}}'::jsonb),
('bednarz',7,'8. Kontrola szczelności i diagnoza przecieków','{"module":2,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Co właściwie kontrolujemy","text":"Kontrola użytkowej beczki obejmuje położenie obręczy, ciągłość klepek, dopasowanie styków, stan denek i zgodność materiałów z przeznaczeniem. Szczelność to wynik określonej próby przeprowadzonej właściwą metodą i w ustalonych warunkach; pojedyncza obserwacja suchego, pustego naczynia nie dowodzi gotowości do kontaktu z żywnością."},{"heading":"Rozpoznaj miejsce usterki","text":"Przeciek wzdłuż klepki sugeruje problem drewna lub krawędzi sąsiednich elementów. Przy krawędzi dna podejrzewa się m.in. wręgę lub denko; w okolicy luźnej obręczy trzeba sprawdzić docisk i geometrię. Nie przyjmuj, że każda wilgotna plama pochodzi z identycznej przyczyny."},{"heading":"Sucha beczka i pęcznienie","text":"Drewno może zmieniać wymiary przy zmianie wilgotności. Niektóre suche beczki użytkowe wymagają procedury kondycjonowania zgodnej z zaleceniami wytwórcy, ale długie moczenie, przypadkowe środki chemiczne albo użycie gorącej wody bez instrukcji mogą uszkodzić wyrób lub pogorszyć higienę."},{"heading":"Przykład zapisu kontroli","text":"Beczka B-04: ślad przy dolnym denku, obręcz nie wykazuje wyraźnego przesunięcia, jedno miejsce ma uszkodzenie drewna. Zamiast wpisu ''beczka cieknie'' wykonaj dokumentację miejsca, stanu surowca, numeru partii oraz decyzji: dalsza diagnoza, naprawa przez fachowca albo wycofanie."},{"heading":"Zadanie diagnostyczne","text":"Przygotuj tabelę z trzema objawami: przeciek na styku dwóch klepek, przeciek przy denku i luźna obręcz. Dla każdego wpisz trzy możliwe przyczyny, obserwację potwierdzającą oraz działanie, którego nie wolno wykonać w ciemno."}],"illustration":"bednarz-diagnoza","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://metc.org/decoding-the-past-cooper/"}],"learning":{"intro":"Kontrola użytkowej beczki obejmuje położenie obręczy, ciągłość klepek, dopasowanie styków, stan denek i zgodność materiałów z przeznaczeniem. Szczelność to wynik określonej próby przeprowadzonej właściwą metodą i w ustalonych warunkach; pojedyncza obserwacja suchego, pustego naczynia nie dowodzi gotowości do kontaktu z żywnością.","situation":"Beczka B-04: ślad przy dolnym denku, obręcz nie wykazuje wyraźnego przesunięcia, jedno miejsce ma uszkodzenie drewna. Zamiast wpisu ''beczka cieknie'' wykonaj dokumentację miejsca, stanu surowca, numeru partii oraz decyzji: dalsza diagnoza, naprawa przez fachowca albo wycofanie.","question":"Przeciek pojawia się wyłącznie przy denku, a nie wzdłuż ścian. Jaka hipoteza jest najbardziej związana z miejscem objawu?","options":["Nieprawidłowe osadzenie denka lub stan rowka croze.","Nieprawidłowa liczba stron w dokumentacji sprzedażowej.","Zbyt duża liczba znaków na etykiecie producenta.","Wyłącznie niska średnia szerokość obręczy przy brzuścu."],"correct":0,"example":"Nieprawidłowe osadzenie denka lub stan rowka croze.","explanation":"Miejsce przy denku kieruje kontrolę w stronę połączenia denka z rowkiem oraz stanu krawędzi, choć ostateczna diagnoza wymaga oględzin.","feedback":["Tak. Miejsce przy denku kieruje kontrolę w stronę połączenia denka z rowkiem oraz stanu krawędzi, choć ostateczna diagnoza wymaga oględzin.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Miejsce przy denku kieruje kontrolę w stronę połączenia denka z rowkiem oraz stanu krawędzi, choć ostateczna diagnoza wymaga oględzin.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Miejsce przy denku kieruje kontrolę w stronę połączenia denka z rowkiem oraz stanu krawędzi, choć ostateczna diagnoza wymaga oględzin.","To nie odpowiada miejscu lub mechanizmowi opisanemu w zadaniu. Miejsce przy denku kieruje kontrolę w stronę połączenia denka z rowkiem oraz stanu krawędzi, choć ostateczna diagnoza wymaga oględzin."],"task":"Przygotuj tabelę z trzema objawami: przeciek na styku dwóch klepek, przeciek przy denku i luźna obręcz. Dla każdego wpisz trzy możliwe przyczyny, obserwację potwierdzającą oraz działanie, którego nie wolno wykonać w ciemno."}}'::jsonb),
('bednarz',8,'9. Beczka do cieczy a naczynie dekoracyjne: wymagania wyrobu','{"module":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Najpierw poznaj zastosowanie","text":"Beczka do płynu i dekoracyjna osłona na kwiaty mogą wyglądać podobnie, ale ich wymagania nie są takie same. Dla naczynia użytkowego liczą się szczelność, stan materiału, możliwa interakcja drewna z zawartością, możliwość czyszczenia i identyfikowalność. W wersji wystawowej dopuszczalna może być patyna, która nie świadczy o gotowości do kontaktu z żywnością."},{"heading":"Gatunek i kontakt z zawartością","text":"Dąb bywa używany do dojrzewania napojów ze względu na strukturę, wytrzymałość i związki chemiczne przechodzące z drewna. Nie oznacza to, że każde stare drewniane naczynie wolno napełnić napojem. Nieznane lakiery, impregnaty, pozostałości i historia użytkowania są istotnymi przeszkodami."},{"heading":"Odbiór nie może być tylko wizualny","text":"Ocena obejmuje dokumentację materiału, oględziny, geometrię, obręcze, szczelność, czystość i warunki transportu. Procedura dopuszczenia do kontaktu z żywnością zależy od zamierzonej zawartości i przepisów. Pozytywna kontrola wymiarów nie zastępuje próby szczelności ani oceny higienicznej."},{"heading":"Przykład dwóch zleceń","text":"Zlecenie A: ekspozycja w restauracji, beczka nie będzie używana do przechowywania produktów. Zlecenie B: nowa beczka do dojrzewania napoju. Dla B należy dodatkowo potwierdzić pochodzenie drewna, proces wytwarzania i bezpieczny stan powierzchni mających kontakt z zawartością."},{"heading":"Zadanie porównawcze","text":"Zrób dwie karty wyrobu: dekoracja oraz pojemnik do napoju. Dla każdej wypisz: zastosowanie, materiały, informacje od klienta, wymagane kontrole, niedopuszczalne odstępstwa i dokument końcowy. Wyjaśnij, dlaczego renowacja zabytku nie nadaje automatycznie statusu wyrobu spożywczego."}],"illustration":"craft-bednarz","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://www.awri.com.au/industry_support/winemaking_resources/storage-and-packaging/packaging-operations/barrel-cleaning-storage-and-maintenance/"}],"learning":{"intro":"Beczka do płynu i dekoracyjna osłona na kwiaty mogą wyglądać podobnie, ale ich wymagania nie są takie same. Dla naczynia użytkowego liczą się szczelność, stan materiału, możliwa interakcja drewna z zawartością, możliwość czyszczenia i identyfikowalność. W wersji wystawowej dopuszczalna może być patyna, która nie świadczy o gotowości do kontaktu z żywnością.","situation":"Zlecenie A: ekspozycja w restauracji, beczka nie będzie używana do przechowywania produktów. Zlecenie B: nowa beczka do dojrzewania napoju. Dla B należy dodatkowo potwierdzić pochodzenie drewna, proces wytwarzania i bezpieczny stan powierzchni mających kontakt z zawartością.","question":"Klient chce przechowywać napój w zabytkowej beczce o nieznanej historii powłok. Co jest właściwą pierwszą decyzją?","options":["Uznać naczynie za bezpieczne, skoro ma metalowe obręcze.","Napełnić je próbnie i ocenić tylko kolor napoju.","Zastosować dowolny uszczelniacz bez sprawdzania jego przeznaczenia.","Nie dopuszczać do zastosowania spożywczego bez ustalenia pochodzenia, stanu i oceny bezpieczeństwa."],"correct":3,"example":"Nie dopuszczać do zastosowania spożywczego bez ustalenia pochodzenia, stanu i oceny bezpieczeństwa.","explanation":"Zdolność do przechowywania żywności nie wynika z samego wyglądu; historia substancji i stan naczynia mogą być krytyczne.","feedback":["Przyjrzyj się wymaganiom technicznym w zadaniu. Zdolność do przechowywania żywności nie wynika z samego wyglądu; historia substancji i stan naczynia mogą być krytyczne.","Przyjrzyj się wymaganiom technicznym w zadaniu. Zdolność do przechowywania żywności nie wynika z samego wyglądu; historia substancji i stan naczynia mogą być krytyczne.","Przyjrzyj się wymaganiom technicznym w zadaniu. Zdolność do przechowywania żywności nie wynika z samego wyglądu; historia substancji i stan naczynia mogą być krytyczne.","Tak. Zdolność do przechowywania żywności nie wynika z samego wyglądu; historia substancji i stan naczynia mogą być krytyczne."],"task":"Zrób dwie karty wyrobu: dekoracja oraz pojemnik do napoju. Dla każdej wypisz: zastosowanie, materiały, informacje od klienta, wymagane kontrole, niedopuszczalne odstępstwa i dokument końcowy. Wyjaśnij, dlaczego renowacja zabytku nie nadaje automatycznie statusu wyrobu spożywczego."}}'::jsonb),
('bednarz',9,'10. Opalanie, prażenie i wpływ drewna na napój','{"module":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Nie każda beczka jest opalana","text":"Proces toasting polega na kontrolowanej obróbce cieplnej wewnętrznej powierzchni niektórych beczek, zwłaszcza używanych do dojrzewania napojów. Charring może prowadzić do silniejszego zwęglenia powierzchni. Dobór technologii zależy od zastosowania, rodzaju drewna i specyfikacji producenta; beczka dekoracyjna nie wymaga naśladowania tego procesu."},{"heading":"Skąd pochodzi różnica aromatu","text":"W drewnie występują związki, które podczas ogrzewania mogą ulegać przekształceniom. Zależnie od warunków można uzyskać inne proporcje związków wpływających na zapach i smak przechowywanych napojów. Nie istnieje prosta zasada, że coraz mocniejsze opalanie zawsze oznacza lepszy efekt."},{"heading":"Rozróżnij obrabianie od użytkowania","text":"Gięcie klepek z użyciem ciepła i wilgoci ma przede wszystkim na celu uzyskanie kształtu. Opalanie wnętrza ma odrębny cel sensoryczny i technologiczny. W praktyce operacje mogą być powiązane w produkcji, ale przy dokumentowaniu jakości powinny mieć osobne nazwy oraz parametry kontrolne."},{"heading":"Przykład decyzji produkcyjnej","text":"Dwa zamówienia mają taki sam rozmiar beczki, lecz inne zastosowanie: jeden klient chce naczynie bez wpływu aromatycznego, drugi zamawia wyrób o określonym stopniu toast. Nie można potraktować obu sztuk identycznie tylko z powodu wspólnych wymiarów."},{"heading":"Ćwiczenie naukowe","text":"Porównaj trzy opisy procesu: zginanie, toasting i charring. Zapisz cel, możliwą zmianę materiału, punkt kontroli i rodzaj ryzyka. Nie próbuj samodzielnie powtarzać procesów termicznych; to ćwiczenie teoretyczne w zakresie rozpoznawania technologii."}],"illustration":"technique-bednarz","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13164676/"}],"learning":{"intro":"Proces toasting polega na kontrolowanej obróbce cieplnej wewnętrznej powierzchni niektórych beczek, zwłaszcza używanych do dojrzewania napojów. Charring może prowadzić do silniejszego zwęglenia powierzchni. Dobór technologii zależy od zastosowania, rodzaju drewna i specyfikacji producenta; beczka dekoracyjna nie wymaga naśladowania tego procesu.","situation":"Dwa zamówienia mają taki sam rozmiar beczki, lecz inne zastosowanie: jeden klient chce naczynie bez wpływu aromatycznego, drugi zamawia wyrób o określonym stopniu toast. Nie można potraktować obu sztuk identycznie tylko z powodu wspólnych wymiarów.","question":"Co przede wszystkim odróżnia toasting od etapu gięcia klepek?","options":["Toasting może modyfikować skład i efekt sensoryczny wewnętrznej powierzchni, a gięcie nadaje kształt.","Toasting wyznacza średnicę obręczy bez zmiany drewna.","Gięcie służy wyłącznie do malowania gotowej beczki.","Toasting jest obowiązkowy dla wszystkich naczyń bednarskich."],"correct":0,"example":"Toasting może modyfikować skład i efekt sensoryczny wewnętrznej powierzchni, a gięcie nadaje kształt.","explanation":"Procesy służą różnym celom: geometrycznemu lub chemiczno-sensorycznemu, choć obie technologie mogą wykorzystywać ciepło.","feedback":["Tak. Procesy służą różnym celom: geometrycznemu lub chemiczno-sensorycznemu, choć obie technologie mogą wykorzystywać ciepło.","Przyjrzyj się wymaganiom technicznym w zadaniu. Procesy służą różnym celom: geometrycznemu lub chemiczno-sensorycznemu, choć obie technologie mogą wykorzystywać ciepło.","Przyjrzyj się wymaganiom technicznym w zadaniu. Procesy służą różnym celom: geometrycznemu lub chemiczno-sensorycznemu, choć obie technologie mogą wykorzystywać ciepło.","Przyjrzyj się wymaganiom technicznym w zadaniu. Procesy służą różnym celom: geometrycznemu lub chemiczno-sensorycznemu, choć obie technologie mogą wykorzystywać ciepło."],"task":"Porównaj trzy opisy procesu: zginanie, toasting i charring. Zapisz cel, możliwą zmianę materiału, punkt kontroli i rodzaj ryzyka. Nie próbuj samodzielnie powtarzać procesów termicznych; to ćwiczenie teoretyczne w zakresie rozpoznawania technologii."}}'::jsonb),
('bednarz',10,'11. Czyszczenie i przechowywanie beczek użytkowych','{"module":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Drewno nie jest stalą nierdzewną","text":"Porowaty materiał może pochłaniać część zawartości. W szczelinach i wewnątrz warstwy drewna mogą pozostawać mikroorganizmy lub osady, dlatego ocena higieny beczki jest trudniejsza niż ocena gładkiego zbiornika metalowego. Sam brak widocznego brudu nie daje pewności, że naczynie jest bezpieczne."},{"heading":"Odbiór i ślad partii","text":"Po dostawie ocenia się uszkodzenia transportowe, zapach wnętrza, czystość, ślady insektów, obręcze i ewentualne plamy. Beczka przeznaczona do wina lub żywności powinna mieć procedurę przygotowania i utrzymania, odpowiednią do historii naczynia i instrukcji producenta."},{"heading":"Dlaczego nie podajemy jednej receptury","text":"Metody czyszczenia, nawilżania i dezynfekcji zależą od napoju, stanu drewna i dostępnego wyposażenia. Nie należy mieszać przypadkowych preparatów ani stosować samodzielnie wysokiego ciśnienia, pary lub chemikaliów. Niektóre zabiegi nie gwarantują usunięcia drobnoustrojów z głębszych warstw drewna."},{"heading":"Przykład wady magazynowej","text":"Nowa beczka jest czysta z zewnątrz, ale wewnątrz czuć nieznany zapach po transporcie. Zamiast napełnienia i maskowania woni trzeba ją odseparować, opisać objaw, sprawdzić dokumentację i zwrócić się do producenta lub właściwego specjalisty."},{"heading":"Zadanie z procedury jakości","text":"Zaprojektuj kartę przyjęcia beczki: ID, dostawca, przeznaczenie, stan powierzchni, zapach, ślady uszkodzeń, status izolacji, decyzja i osoba odpowiedzialna. Osobno stwórz schemat reakcji na podejrzenie zanieczyszczenia mikrobiologicznego."}],"illustration":"bednarz-diagnoza","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://www.awri.com.au/industry_support/winemaking_resources/storage-and-packaging/packaging-operations/barrel-cleaning-storage-and-maintenance/"}],"learning":{"intro":"Porowaty materiał może pochłaniać część zawartości. W szczelinach i wewnątrz warstwy drewna mogą pozostawać mikroorganizmy lub osady, dlatego ocena higieny beczki jest trudniejsza niż ocena gładkiego zbiornika metalowego. Sam brak widocznego brudu nie daje pewności, że naczynie jest bezpieczne.","situation":"Nowa beczka jest czysta z zewnątrz, ale wewnątrz czuć nieznany zapach po transporcie. Zamiast napełnienia i maskowania woni trzeba ją odseparować, opisać objaw, sprawdzić dokumentację i zwrócić się do producenta lub właściwego specjalisty.","question":"Dlaczego wizualnie czysta używana beczka nie musi być gotowa do ponownego napełnienia?","options":["Ponieważ każda beczka jest jednorazowa.","Ponieważ drewno może zatrzymywać osady i drobnoustroje także poza widoczną powierzchnią.","Ponieważ stalowe obręcze są zawsze źródłem zanieczyszczeń mikrobiologicznych.","Ponieważ wszystkie używane beczki mają identyczną historię przechowywania."],"correct":1,"example":"Ponieważ drewno może zatrzymywać osady i drobnoustroje także poza widoczną powierzchnią.","explanation":"Porowatość i wcześniejsze użycie utrudniają ocenę higieniczną; wymagane są właściwe procedury czyszczenia i weryfikacji.","feedback":["Przyjrzyj się wymaganiom technicznym w zadaniu. Porowatość i wcześniejsze użycie utrudniają ocenę higieniczną; wymagane są właściwe procedury czyszczenia i weryfikacji.","Tak. Porowatość i wcześniejsze użycie utrudniają ocenę higieniczną; wymagane są właściwe procedury czyszczenia i weryfikacji.","Przyjrzyj się wymaganiom technicznym w zadaniu. Porowatość i wcześniejsze użycie utrudniają ocenę higieniczną; wymagane są właściwe procedury czyszczenia i weryfikacji.","Przyjrzyj się wymaganiom technicznym w zadaniu. Porowatość i wcześniejsze użycie utrudniają ocenę higieniczną; wymagane są właściwe procedury czyszczenia i weryfikacji."],"task":"Zaprojektuj kartę przyjęcia beczki: ID, dostawca, przeznaczenie, stan powierzchni, zapach, ślady uszkodzeń, status izolacji, decyzja i osoba odpowiedzialna. Osobno stwórz schemat reakcji na podejrzenie zanieczyszczenia mikrobiologicznego."}}'::jsonb),
('bednarz',11,'12. Kalkulacja materiału, obręczy i kosztu projektu','{"module":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Ilość części to dopiero początek","text":"Zestawienie materiałów zawiera liczbę i wymiary klepek, ilość elementów denka, liczbę obręczy, typ łączenia oraz naddatek technologiczny. Nie wystarczy policzyć samego drewna: w procesie występuje selekcja z wad, odrzuty przy rozkroju, struganie, gięcie, przygotowanie dna, próby i dokumentacja."},{"heading":"Oblicz przykład liczby klepek","text":"Projekt zakłada 24 klepki. Przyjmij przykładowo, że 15% przygotowanych klepek może zostać odrzuconych przed montażem. Szacunkowe zamówienie to 24/0,85 = 28,24, więc w założeniu całych sztuk zaplanujesz co najmniej 29 kandydatów. To szacunek, nie deklaracja rzeczywistej wydajności każdej produkcji."},{"heading":"Narzut, marża i robocizna","text":"Załóż 29 kandydatów po 25 zł (725 zł), obręcze 200 zł, inne materiały 75 zł i 6 godzin pracy po 80 zł (480 zł). Suma kosztów bezpośrednich w tym modelu wynosi 1480 zł. Jeśli cena sprzedaży wynosi 2000 zł, różnica 520 zł musi jeszcze pokryć koszty pośrednie, ryzyko oraz podatek zgodnie z przyjętą metodą."},{"heading":"Zależności w harmonogramie","text":"Część operacji zależy od poprzedniej: bez odpowiednio przygotowanego drewna nie można przystąpić do zestawienia; bez zgodnej geometrii nie ma sensu osadzać denka. Sezonowanie może zajmować znacznie więcej niż czas ręcznego montażu, dlatego terminu realizacji nie ustala się z samej liczby roboczogodzin."},{"heading":"Ćwiczenie w arkuszu","text":"Zbuduj tabelę: materiał, liczba jednostek, koszt jednostki, koszt łączny, odrzut, koszt robocizny, koszty dodatkowe. Przelicz wariant 10% odrzutu zamiast 15% i porównaj plan zakupów. Zaznacz koszty potwierdzone i przyjęte do symulacji."}],"illustration":"bednarz-geometria","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://www.saury.com/en/our-skills/the-stages-of-barrel-making/"}],"learning":{"intro":"Zestawienie materiałów zawiera liczbę i wymiary klepek, ilość elementów denka, liczbę obręczy, typ łączenia oraz naddatek technologiczny. Nie wystarczy policzyć samego drewna: w procesie występuje selekcja z wad, odrzuty przy rozkroju, struganie, gięcie, przygotowanie dna, próby i dokumentacja.","situation":"Część operacji zależy od poprzedniej: bez odpowiednio przygotowanego drewna nie można przystąpić do zestawienia; bez zgodnej geometrii nie ma sensu osadzać denka. Sezonowanie może zajmować znacznie więcej niż czas ręcznego montażu, dlatego terminu realizacji nie ustala się z samej liczby roboczogodzin.","question":"Do beczki potrzeba 24 poprawnych klepek; planistyczny odrzut wynosi 15%. Ile kandydatów należy przygotować przy tym uproszczonym założeniu?","options":["25, bo wystarczy dodać jedną sztukę.","28, bo wynik 28,24 zawsze zaokrągla się w dół.","29, bo 24/0,85 ≈ 28,24 i liczymy całe sztuki.","35, bo 15% zawsze oznacza dołożenie jedenastu sztuk."],"correct":2,"example":"29, bo 24/0,85 ≈ 28,24 i liczymy całe sztuki.","explanation":"Aby z planistyczną wydajnością 85% otrzymać 24 poprawne sztuki, 24/0,85≈28,24; potrzebna liczba całych kandydatów to minimum 29.","feedback":["Przyjrzyj się wymaganiom technicznym w zadaniu. Aby z planistyczną wydajnością 85% otrzymać 24 poprawne sztuki, 24/0,85≈28,24; potrzebna liczba całych kandydatów to minimum 29.","Przyjrzyj się wymaganiom technicznym w zadaniu. Aby z planistyczną wydajnością 85% otrzymać 24 poprawne sztuki, 24/0,85≈28,24; potrzebna liczba całych kandydatów to minimum 29.","Tak. Aby z planistyczną wydajnością 85% otrzymać 24 poprawne sztuki, 24/0,85≈28,24; potrzebna liczba całych kandydatów to minimum 29.","Przyjrzyj się wymaganiom technicznym w zadaniu. Aby z planistyczną wydajnością 85% otrzymać 24 poprawne sztuki, 24/0,85≈28,24; potrzebna liczba całych kandydatów to minimum 29."],"task":"Zbuduj tabelę: materiał, liczba jednostek, koszt jednostki, koszt łączny, odrzut, koszt robocizny, koszty dodatkowe. Przelicz wariant 10% odrzutu zamiast 15% i porównaj plan zakupów. Zaznacz koszty potwierdzone i przyjęte do symulacji."}}'::jsonb),
('bednarz',12,'13. Diagnostyka wad: od objawu do przyczyny','{"module":4,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Oddziel objaw od hipotezy","text":"Objawem jest np. mokra smuga na określonej wysokości, a hipotezą — niewłaściwy styk klepek, pęknięcie lub uszkodzenie rowka denka. Nie wolno uznać pierwszej hipotezy za potwierdzoną bez oględzin. Zamiast ''nie działa'' używaj lokalizacji, czasu, warunków i historii naczynia."},{"heading":"Mapa wad płaszcza","text":"Długie ślady wzdłuż styków mogą wskazywać niedopasowanie krawędzi, zmiany wilgotności lub stan obręczy. Punktowe wycieki przez drewno mogą sugerować pęknięcie albo lokalną wadę. Wady związane z końcem naczynia kierują uwagę na wręgę, denko i zewnętrzne krawędzie."},{"heading":"Mapa wad obręczy","text":"Przesunięta, odkształcona lub uszkodzona obręcz może zmienić rozkład docisku. Nie oznacza to, że zawsze trzeba ją mocniej pobić: należy ocenić stan metalu, zgodność średnicy z płaszczem, położenie i ewentualne pęknięcia drewna. Nie podejmuj mechanicznej naprawy bez odpowiedniego stanowiska."},{"heading":"Przykład dokumentacji","text":"Wyrób B-17: po wyschnięciu magazynowym pojawił się przeciek wzdłuż klepki nr 6, stwierdzono pęknięcie przez grubość. Opis ''dociśnięto obręcz, zniknął objaw'' nie jest równoznaczny z bezpieczną naprawą; uszkodzoną klepkę ocenia specjalista, a wyrób wymaga ponownego odbioru."},{"heading":"Praca ucznia","text":"Przygotuj drzewo decyzji dla czterech objawów: wilgotna smuga przy denku, podłużny przeciek, rdzewiejąca obręcz i nieznany zapach. Dla każdego: co zmierzyć, co sfotografować, jaką hipotezę sprawdzić i kiedy wyłączyć naczynie z użycia."}],"illustration":"bednarz-diagnoza","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://www.enotools.com/uploads/2/3/9/7/2397754/barrel_associates_american_oak_quality_control_guidelines.pdf"}],"learning":{"intro":"Objawem jest np. mokra smuga na określonej wysokości, a hipotezą — niewłaściwy styk klepek, pęknięcie lub uszkodzenie rowka denka. Nie wolno uznać pierwszej hipotezy za potwierdzoną bez oględzin. Zamiast ''nie działa'' używaj lokalizacji, czasu, warunków i historii naczynia.","situation":"Wyrób B-17: po wyschnięciu magazynowym pojawił się przeciek wzdłuż klepki nr 6, stwierdzono pęknięcie przez grubość. Opis ''dociśnięto obręcz, zniknął objaw'' nie jest równoznaczny z bezpieczną naprawą; uszkodzoną klepkę ocenia specjalista, a wyrób wymaga ponownego odbioru.","question":"Co jest prawidłową reakcją na podłużne pęknięcie klepki przechodzące przez jej grubość?","options":["Uznanie, że każda usterka zostanie trwale usunięta przez obręcz.","Zalanie pęknięcia dowolnym klejem i natychmiastowy odbiór higieniczny.","Pominięcie dokumentacji, jeżeli przeciek chwilowo zniknął.","Wycofanie do fachowej oceny, udokumentowanie uszkodzenia i ponowna kontrola po naprawie."],"correct":3,"example":"Wycofanie do fachowej oceny, udokumentowanie uszkodzenia i ponowna kontrola po naprawie.","explanation":"Pęknięcie przez grubość jest wadą materiałową; poprawa docisku nie musi usunąć przyczyny ani zapewnić bezpieczeństwa.","feedback":["Przyjrzyj się wymaganiom technicznym w zadaniu. Pęknięcie przez grubość jest wadą materiałową; poprawa docisku nie musi usunąć przyczyny ani zapewnić bezpieczeństwa.","Przyjrzyj się wymaganiom technicznym w zadaniu. Pęknięcie przez grubość jest wadą materiałową; poprawa docisku nie musi usunąć przyczyny ani zapewnić bezpieczeństwa.","Przyjrzyj się wymaganiom technicznym w zadaniu. Pęknięcie przez grubość jest wadą materiałową; poprawa docisku nie musi usunąć przyczyny ani zapewnić bezpieczeństwa.","Tak. Pęknięcie przez grubość jest wadą materiałową; poprawa docisku nie musi usunąć przyczyny ani zapewnić bezpieczeństwa."],"task":"Przygotuj drzewo decyzji dla czterech objawów: wilgotna smuga przy denku, podłużny przeciek, rdzewiejąca obręcz i nieznany zapach. Dla każdego: co zmierzyć, co sfotografować, jaką hipotezę sprawdzić i kiedy wyłączyć naczynie z użycia."}}'::jsonb),
('bednarz',13,'14. Odbiór jakości: dokumentacja i ślad produkcji','{"module":4,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Co jest wynikiem jakości","text":"Dobry protokół nie kończy się zdaniem ''beczka gotowa''. Powinien łączyć wymaganie klienta z identyfikatorem wyrobu, partią drewna, stanem klepek, obręczy i denek, kontrolą geometrii oraz właściwą próbą dla przeznaczenia. Wymagania muszą być ustalone przed produkcją."},{"heading":"Kontrola międzyoperacyjna","text":"Właściwości materiału sprawdza się przed obróbką, geometrię klepek przed zestawieniem, stan płaszcza po gięciu, rowek i denko przed zamknięciem oraz szczelność po złożeniu. Późna kontrola nie zastąpi etapowej: ukrytego uszkodzenia wewnątrz płaszcza może nie być widać z zewnątrz."},{"heading":"Numer partii jest ważny","text":"Jeśli dwie beczki z tej samej partii mają zbliżoną wadę, informacje o dostawcy drewna, czasie przygotowania i zastosowanej technologii mogą pomóc ustalić wspólną przyczynę. Bez przypisania partii i dat jedynym dostępnym rozwiązaniem bywa chaotyczna naprawa każdej sztuki osobno."},{"heading":"Przykład odchyleń","text":"Dla partii 12 beczek sprawdzono 12 razy stan obręczy i geometrię. Dwie nie przeszły próby szczelności, jedna miała pękniętą klepkę. Nie wolno obliczyć liczby niezgodnych sztuk jako 3 bez sprawdzenia, czy uszkodzenie dotyczyło jednej z dwóch nieszczelnych beczek."},{"heading":"Zadanie protokołu","text":"Zaprojektuj kartę z 15 polami. Rozdziel dane identyfikacyjne, materiały, wynik kontroli, rodzaj niezgodności, działanie korygujące, re-test i zatwierdzenie. Dodaj kolumny ''wymaganie'', ''wynik'', ''dowód'' i ''decyzja'', aby uczeń mógł ocenić wyrób na podstawie faktów."}],"illustration":"bednarz-diagnoza","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://www.enotools.com/uploads/2/3/9/7/2397754/barrel_associates_american_oak_quality_control_guidelines.pdf"}],"learning":{"intro":"Dobry protokół nie kończy się zdaniem ''beczka gotowa''. Powinien łączyć wymaganie klienta z identyfikatorem wyrobu, partią drewna, stanem klepek, obręczy i denek, kontrolą geometrii oraz właściwą próbą dla przeznaczenia. Wymagania muszą być ustalone przed produkcją.","situation":"Dla partii 12 beczek sprawdzono 12 razy stan obręczy i geometrię. Dwie nie przeszły próby szczelności, jedna miała pękniętą klepkę. Nie wolno obliczyć liczby niezgodnych sztuk jako 3 bez sprawdzenia, czy uszkodzenie dotyczyło jednej z dwóch nieszczelnych beczek.","question":"W partii 12 beczek dwie nie przeszły próby szczelności, a jedna ma pękniętą klepkę. Dlaczego liczba wadliwych sztuk nie musi wynosić trzy?","options":["Bo prób szczelności nie zapisuje się w protokole.","Bo pęknięta klepka może znajdować się w jednej z dwóch już policzonych nieszczelnych beczek.","Bo każda beczka z obręczami jest z definicji szczelna.","Bo wynik jakości zależy tylko od koloru drewna."],"correct":1,"example":"Bo pęknięta klepka może znajdować się w jednej z dwóch już policzonych nieszczelnych beczek.","explanation":"Bez identyfikatorów i przypisania usterek do sztuk nie można sumować liczby niezgodności jako liczby unikalnych wyrobów.","feedback":["Przyjrzyj się wymaganiom technicznym w zadaniu. Bez identyfikatorów i przypisania usterek do sztuk nie można sumować liczby niezgodności jako liczby unikalnych wyrobów.","Tak. Bez identyfikatorów i przypisania usterek do sztuk nie można sumować liczby niezgodności jako liczby unikalnych wyrobów.","Przyjrzyj się wymaganiom technicznym w zadaniu. Bez identyfikatorów i przypisania usterek do sztuk nie można sumować liczby niezgodności jako liczby unikalnych wyrobów.","Przyjrzyj się wymaganiom technicznym w zadaniu. Bez identyfikatorów i przypisania usterek do sztuk nie można sumować liczby niezgodności jako liczby unikalnych wyrobów."],"task":"Zaprojektuj kartę z 15 polami. Rozdziel dane identyfikacyjne, materiały, wynik kontroli, rodzaj niezgodności, działanie korygujące, re-test i zatwierdzenie. Dodaj kolumny ''wymaganie'', ''wynik'', ''dowód'' i ''decyzja'', aby uczeń mógł ocenić wyrób na podstawie faktów."}}'::jsonb),
('bednarz',14,'15. Renowacja: zabytek, naczynie użytkowe i granice naprawy','{"module":4,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Najpierw określ cel","text":"Konserwacja zabytkowej beczki może polegać na zachowaniu materiału, napisów i śladów użytkowania, a nie na przywróceniu jej szczelności. Odnowienie funkcji użytkowej to inny cel, wymagający oceny bezpieczeństwa i higieny. Dla historycznych przedmiotów ingerencja może usunąć informacje cenne dla muzeum."},{"heading":"Mapa stanu przed pracą","text":"W dokumentacji zaznacz pęknięcia, ślady biologiczne, zużycie obręczy, deformacje, wcześniejsze naprawy i warstwy wykończeniowe. Zapisz datę, numer obiektu, zdjęcia z miarką oraz nieznane elementy historii. Nie myj, nie impregnuj i nie wymieniaj elementów tylko dlatego, że wyglądają staro."},{"heading":"Czego nie naprawia klej","text":"Przypadkowy klej lub uszczelniacz może zmienić wygląd, utrudnić przyszłą konserwację i nie spełniać wymagań dla żywności. Warto rozróżniać naprawę strukturalną, konserwację powierzchni i uszczelnienie. Każde działanie ma odrębny warunek dopuszczenia i możliwość pozostawienia śladu w dokumentacji."},{"heading":"Przykład zabytku","text":"Beczka z sygnaturą starego zakładu ma spękaną obręcz i przebarwienie. Właściciel chce ją wystawić, nie używać do napojów. Najważniejsze jest zabezpieczenie przed dalszym uszkodzeniem i zachowanie sygnatury, a nie pozbycie się wszystkich śladów wieku."},{"heading":"Ćwiczenie konserwatorskie","text":"Sporządź dwa warianty planu dla tego samego obiektu: ekspozycja w muzeum i próba przywrócenia funkcji użytkowej. Wskaż, jakich dowodów wymaga każda decyzja oraz kiedy potrzebna jest ocena konserwatora albo producenta specjalistycznego."}],"illustration":"craft-bednarz","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://metc.org/decoding-the-past-cooper/"}],"learning":{"intro":"Konserwacja zabytkowej beczki może polegać na zachowaniu materiału, napisów i śladów użytkowania, a nie na przywróceniu jej szczelności. Odnowienie funkcji użytkowej to inny cel, wymagający oceny bezpieczeństwa i higieny. Dla historycznych przedmiotów ingerencja może usunąć informacje cenne dla muzeum.","situation":"Beczka z sygnaturą starego zakładu ma spękaną obręcz i przebarwienie. Właściciel chce ją wystawić, nie używać do napojów. Najważniejsze jest zabezpieczenie przed dalszym uszkodzeniem i zachowanie sygnatury, a nie pozbycie się wszystkich śladów wieku.","question":"Dlaczego zabytkowej beczki z oryginalną sygnaturą nie należy automatycznie zeszlifować do nowego drewna?","options":["Ponieważ wszystkie stare powłoki są bezpieczne do kontaktu z napojem.","Ponieważ każdy stary przedmiot powinien być bezwarunkowo szczelny.","Ponieważ mogłoby to nieodwracalnie usunąć wartościowe historycznie ślady.","Ponieważ po szlifowaniu drewno przestaje chłonąć wilgoć."],"correct":2,"example":"Ponieważ mogłoby to nieodwracalnie usunąć wartościowe historycznie ślady.","explanation":"Celem konserwacji może być zachowanie autentycznych informacji o obiekcie, a nie jego wizualne odmłodzenie.","feedback":["Przyjrzyj się wymaganiom technicznym w zadaniu. Celem konserwacji może być zachowanie autentycznych informacji o obiekcie, a nie jego wizualne odmłodzenie.","Przyjrzyj się wymaganiom technicznym w zadaniu. Celem konserwacji może być zachowanie autentycznych informacji o obiekcie, a nie jego wizualne odmłodzenie.","Tak. Celem konserwacji może być zachowanie autentycznych informacji o obiekcie, a nie jego wizualne odmłodzenie.","Przyjrzyj się wymaganiom technicznym w zadaniu. Celem konserwacji może być zachowanie autentycznych informacji o obiekcie, a nie jego wizualne odmłodzenie."],"task":"Sporządź dwa warianty planu dla tego samego obiektu: ekspozycja w muzeum i próba przywrócenia funkcji użytkowej. Wskaż, jakich dowodów wymaga każda decyzja oraz kiedy potrzebna jest ocena konserwatora albo producenta specjalistycznego."}}'::jsonb),
('bednarz',15,'16. Projekt końcowy: specyfikacja i diagnoza beczki','{"module":4,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","curriculum_revision":3,"sections":[{"heading":"Twoje zlecenie","text":"Wyobraź sobie nową dekoracyjną beczkę o wysokości 900 mm, średnicy przy brzuścu 600 mm i średnicy końców 500 mm. Klient chce widoczne obręcze, jedno denko zdejmowane wyłącznie jako element ekspozycji i bez kontaktu z żywnością. Ma być bezpiecznie ustawiona w pomieszczeniu, a dokumentacja musi umożliwić ocenę wykonania."},{"heading":"Pierwszy rachunek","text":"Obwód zewnętrzny przy brzuścu to 600π ≈ 1885 mm; przy końcu 500π ≈ 1571 mm. Przy 20 klepkach średni udział obwodu wynosi odpowiednio 94,25 i 78,55 mm. Nie podawaj tych liczb jako gotowego szablonu klepki: profil, grubość, kąty i obróbka muszą być doprojektowane."},{"heading":"Lista materiału i ryzyk","text":"Przygotuj listę drewna z gatunkiem i cechami włókien, plan liczby klepek wraz z naddatkiem, zestaw obręczy, denko oraz ewentualny stabilny stojak. Zaznacz ryzyka: ostre krawędzie obręczy, niestabilność, pęknięcia i źle dopasowana geometria."},{"heading":"Jak odebrać efekt","text":"Przed uznaniem za gotowy sprawdź wymiar zewnętrzny na kilku wysokościach, stan klepek, ostre krawędzie, rozmieszczenie obręczy, stabilność ustawienia i zgodność z rysunkiem. Nie wykonuj próby napojowej, ponieważ wyrób nie jest zamawiany do kontaktu z cieczami ani do żywności."},{"heading":"Egzamin weryfikujący zrozumienie","text":"Oddaj szkic z trzema widokami, tabelę materiałów, obliczenia obu obwodów, punktowe kontrole i raport błędu. Dodatkowy scenariusz: po montażu pojawia się szczelina przy klepce nr 8. Wyjaśnij, jakie pomiary i oględziny wykonasz przed decyzją o poprawce."}],"illustration":"bednarz-geometria","references":[{"label":"Źródło techniczne do dalszej lektury","url":"https://www.saury.com/en/our-skills/the-stages-of-barrel-making/"}],"learning":{"intro":"Wyobraź sobie nową dekoracyjną beczkę o wysokości 900 mm, średnicy przy brzuścu 600 mm i średnicy końców 500 mm. Klient chce widoczne obręcze, jedno denko zdejmowane wyłącznie jako element ekspozycji i bez kontaktu z żywnością. Ma być bezpiecznie ustawiona w pomieszczeniu, a dokumentacja musi umożliwić ocenę wykonania.","situation":"Przed uznaniem za gotowy sprawdź wymiar zewnętrzny na kilku wysokościach, stan klepek, ostre krawędzie, rozmieszczenie obręczy, stabilność ustawienia i zgodność z rysunkiem. Nie wykonuj próby napojowej, ponieważ wyrób nie jest zamawiany do kontaktu z cieczami ani do żywności.","question":"Dlaczego w końcowym projekcie nie można przyjąć 94,25 mm jako szerokości każdej klepki na całej wysokości?","options":["Bo beczka ma różne obwody na wysokości, a wynik C/N jest tylko uśrednionym udziałem obwodu w jednej strefie.","Bo liczba klepek nie ma żadnego związku z obwodem.","Bo średnica końca zawsze równa się średnicy brzuśca.","Bo nie da się w ogóle określić średnicy beczki na rysunku."],"correct":0,"example":"Bo beczka ma różne obwody na wysokości, a wynik C/N jest tylko uśrednionym udziałem obwodu w jednej strefie.","explanation":"Zmienna średnica i geometria sąsiadujących styków wymagają rzeczywistego szablonu, nie jednego średniego wymiaru.","feedback":["Tak. Zmienna średnica i geometria sąsiadujących styków wymagają rzeczywistego szablonu, nie jednego średniego wymiaru.","Przyjrzyj się wymaganiom technicznym w zadaniu. Zmienna średnica i geometria sąsiadujących styków wymagają rzeczywistego szablonu, nie jednego średniego wymiaru.","Przyjrzyj się wymaganiom technicznym w zadaniu. Zmienna średnica i geometria sąsiadujących styków wymagają rzeczywistego szablonu, nie jednego średniego wymiaru.","Przyjrzyj się wymaganiom technicznym w zadaniu. Zmienna średnica i geometria sąsiadujących styków wymagają rzeczywistego szablonu, nie jednego średniego wymiaru."],"task":"Oddaj szkic z trzema widokami, tabelę materiałów, obliczenia obu obwodów, punktowe kontrole i raport błędu. Dodatkowy scenariusz: po montażu pojawia się szczelina przy klepce nr 8. Wyjaśnij, jakie pomiary i oględziny wykonasz przed decyzją o poprawce."}}'::jsonb)
on conflict(course_slug,lesson_no) do update set
title_pl=excluded.title_pl,material=public.ta_lessons.material||excluded.material,updated_at=now();
update public.ta_courses set description_pl='16 lekcji o bednarstwie od podstaw: budowa beczki i materiałoznawstwo, narzędzia i ich konserwacja, rysunek techniczny i geometria klepek, przygotowanie i gięcie, wręga i denko, szczelność, higiena, opalanie, kosztorys, kontrola jakości oraz projekt końcowy. Kurs edukacyjny, nie nadaje kwalifikacji zawodowych; wymaga nadzorowanej praktyki warsztatowej.' where slug='bednarz';
update public.ta_course_previews set
curiosity='Dlaczego beczka może być szczelna bez kleju — i dlaczego dwie odmiany dębu wymagają innego przygotowania?',
scenario='Dostajesz rysunek beczki 600 mm średnicy w brzuścu, 500 mm przy końcu i 20 klepek. Wyznacz szacunkowe obwody, rozpoznaj rowek na denko i zaproponuj kontrolę przecieku.',
outcome_1='Rozpoznasz części beczki, narzędzia, właściwości drewna i różnicę między naczyniem dekoracyjnym a użytkowym.',
outcome_2='Policzysz obwód i orientacyjne udziały klepek, a także przygotujesz zestawienie materiałów i prosty kosztorys.',
outcome_3='Opracujesz plan kontroli jakości, diagnozy przecieku i końcowy rysunek techniczny beczki.',
source_url='https://metc.org/decoding-the-past-cooper/',
module_titles='["1. Fundamenty, drewno i geometria (lekcje 1–4)","2. Formowanie, denko i szczelność (lekcje 5–8)","3. Zastosowanie, higiena i kalkulacja (lekcje 9–12)","4. Diagnostyka, jakość i projekt końcowy (lekcje 13–16)"]'::jsonb,
review_status='review_needed',
editorial_note='16 opracowań edukacyjnych z przykładami obliczeń, pytaniami i ćwiczeniami. Wymagana recenzja fachowego bednarza, test użytkownika od lekcji do egzaminu i praktyka z instruktorem. Kurs nie jest formalnym przygotowaniem do państwowego egzaminu ani dowodem uprawnień.'
where course_slug='bednarz';
COMMIT;
